   Runtime sections use MATRIX_ matrixDim/register/condition plus set_CODE,
   matrix_mult_CODE, matrix_matXvec_CODE, matrix_add_CODE/subtract_CODE,
   matrix_scalarMult_CODE, MATH_matx_invert,
   mat_2x2_sym_inv_code, mat_3x3_sym_inv_code. */
/* RTDS lifecycle placement for a network with no eliminated internal nodes.
   No Schur complement is required: use the original G matrix and Ihis vector directly. */
STATIC:

    int B3_case_id = 0;
    double A = 0.0;
    double Gc_0 = 0.0;
    double Gc_1 = 0.0;
    double Y = 0.0;
    double Z = 0.0;

    /* Runtime matrix objects */
    /* Runtime state */
    int rtds_matrix_code_ready = 0;
    /* User G/CODE symbols */
    double multcase_G_B3_N4_N4 = 0.0;

LOCAL_STATIC:
    /* User RAM-only G symbols */
    double Ga = 0.0;
    double Gb = 0.0;

RAM_PASS1:
    /* Decode the optional global case selector into per-element local cases. */
    switch (case_id) {
    case 0: /* case 0: R3 = Case 0; B3=case0 */
        B3_case_id = 0;
        break;
    case 1: /* case 1: R3 = Case 1; B3=case1 */
        B3_case_id = 1;
        break;
    default:
        B3_case_id = 0;
        break;
    }
    int err = 0;
    /* ************************************************************************
     * RAM-SIDE G MATRIX VALUE SETUP
     * No internal nodes are selected, so fixed RAM G stamping uses the original G matrix.
     * Assign or compute every G-related value before writing g_mat_over.
     * Dynamic entries are registered in GVALUES and refreshed in CODE.
     * ************************************************************************ */


    /* Case-conditional RAM final-G stamp. Each init-time case gets its own compact RAM overlay. */
    switch (case_id) {
    case 0:
        /* CODE-owned case: no RAM stamp for varG_n1b_N5. */
        /* CODE-owned case: no RAM stamp for varG_N5_N5. */
        g_mat_nods[0] = getNodeNum(comp, "n1a");
        g_mat_nods[1] = getNodeNum(comp, "n1b");
        g_mat_nods[2] = getNodeNum(comp, "n2a");
        for (int row = 0; row < 3; row++) {
            for (int col = 0; col < 3; col++) {
                g_mat_over[row][col] = 0.0;
            }
        }
        g_mat_over[0][0] = Ga;
        g_mat_over[0][1] = -Ga;
        g_mat_over[1][0] = -Ga;
        g_mat_over[1][1] = Ga + Gb;
        g_mat_over[1][2] = -Gb;
        g_mat_over[2][1] = -Gb;
        g_mat_over[2][2] = Gb;
        setupGMatrix(3);
        break;
    case 1:
        g_mat_nods[0] = getNodeNum(comp, "n1a");
        g_mat_nods[1] = getNodeNum(comp, "n1b");
        g_mat_nods[2] = getNodeNum(comp, "n2a");
        g_mat_nods[3] = getNodeNum(comp, "N5");
        for (int row = 0; row < 4; row++) {
            for (int col = 0; col < 4; col++) {
                g_mat_over[row][col] = 0.0;
            }
        }
        g_mat_over[0][0] = Ga;
        g_mat_over[0][1] = -Ga;
        g_mat_over[1][0] = -Ga;
        g_mat_over[1][1] = Ga + Gb + Y;
        g_mat_over[1][2] = -Gb;
        g_mat_over[2][1] = -Gb;
        g_mat_over[1][3] = -Y;
        g_mat_over[3][1] = -Y;
        g_mat_over[2][2] = Gb;
        g_mat_over[3][3] = Y;
        setupGMatrix(4);
        break;
    default:
        reportError_RW("network_node", STOP_IMMEDIATELY_CONDITION,
                       "Invalid multi-case case_id %d for component %s.",
                       case_id, Name);
        break;
    }

    if (err > 0) {
        reportError_RW("network_node", STOP_IMMEDIATELY_CONDITION,
                       "RTDS matrix allocation failed for component %s.", Name);
    }

GVALUES:
    /* Dynamic original-G stamp handles, ordered by upper triangle. */
    double varG_n1b_n1b = createGValue("varG_n1b_n1b", "n1b", "n1b", 0, "case_id == 0 || case_id == 1");
    double varG_n1b_N5 = createGValue("varG_n1b_N5", "n1b", "N5", 0, "case_id == 0 || case_id == 1");
    double varG_N5_N5 = createGValue("varG_N5_N5", "N5", "N5", 0, "case_id == 0 || case_id == 1");

CODE:
BEGIN_T0:
    /* CODE final-G cases write full case values directly below;
       RAM-owned cases were stamped in RAM_PASS1. */
    if (!rtds_matrix_code_ready) {
        initializeMatricesForCode();
        rtds_matrix_code_ready = 1;
    }

    /* ************************************************************************
     * CODE-SIDE G MATRIX VALUE SETUP
     * No-internal multi-case path: write only CODE-owned final G entries
     * under their active case condition. RAM-owned cases stay in RAM_PASS1.
     * ************************************************************************ */

    /* Case-conditional CODE final-G writes.
       RAM-owned cases were stamped in RAM_PASS1; no base + delta is generated. */
    switch (case_id) {
    case 0:
        varG_n1b_n1b = A*Z + Gc_0 + Y;
        varG_n1b_N5 = -A*Z - Gc_0 - Y;
        varG_N5_N5 = A*Z + Gc_0 + Y;
        break;
    case 1:
        varG_n1b_n1b = A*Z + Gc_1;
        varG_n1b_N5 = -A*Z - Gc_1;
        varG_N5_N5 = A*Z + Gc_1;
        break;
    default:
        break;
    }

    /* ************************************************************************
     * CODE-SIDE IHIS VALUE SETUP
     * Update runtime Ihis/history-source values before node-current injection.
     * No internal nodes are eliminated, so assign original Ihis entries directly to Inj.
     * The row order follows the original retained-node order.
     * ************************************************************************ */



    /* Node injection currents follow the retained-node order of the original system. */
    Injn1a = 0.0;
    Injn1b = 0.0;
    Injn2a = 0.0;
    InjN5 = 0.0;

